-- Explicit personnel cover plans preserve original task facts, not actual assignments.
CREATE TABLE staff_cover_roots(id TEXT PRIMARY KEY,absence_id TEXT NOT NULL REFERENCES staff_record_roots(id),staff_id TEXT NOT NULL REFERENCES users(id),store_id TEXT NOT NULL REFERENCES stores(id),serial INTEGER NOT NULL CHECK(serial>0),cover_number TEXT NOT NULL,first_version_id TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(store_id,serial),UNIQUE(store_id,cover_number),FOREIGN KEY(first_version_id,id) REFERENCES staff_cover_versions(id,root_id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE staff_cover_versions(id TEXT PRIMARY KEY,root_id TEXT NOT NULL REFERENCES staff_cover_roots(id),store_id TEXT NOT NULL REFERENCES stores(id),version INTEGER NOT NULL CHECK(version>0),base_sequence INTEGER NOT NULL CHECK(base_sequence>=0),event_id TEXT NOT NULL UNIQUE,absence_version_id TEXT NOT NULL REFERENCES staff_record_versions(id),absence_event_id TEXT NOT NULL REFERENCES staff_record_events(id),staff_snapshot_json TEXT NOT NULL CHECK(json_valid(staff_snapshot_json)),task_completion_prefix INTEGER NOT NULL CHECK(task_completion_prefix>=0),task_event_prefix INTEGER NOT NULL CHECK(task_event_prefix>=0),staff_record_sequence INTEGER NOT NULL CHECK(staff_record_sequence>=0),title TEXT NOT NULL,source_reference TEXT NOT NULL,source_note TEXT NOT NULL,reason TEXT NOT NULL,item_count INTEGER NOT NULL CHECK(item_count BETWEEN 1 AND 30),created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(root_id,version),UNIQUE(id,root_id),FOREIGN KEY(event_id,id) REFERENCES staff_cover_events(id,version_id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE staff_cover_items(version_id TEXT NOT NULL REFERENCES staff_cover_versions(id),position INTEGER NOT NULL CHECK(position BETWEEN 1 AND 30),task_id TEXT NOT NULL,task_revision INTEGER NOT NULL,recipient_id TEXT NOT NULL REFERENCES users(id),recipient_snapshot_json TEXT NOT NULL CHECK(json_valid(recipient_snapshot_json)),coverage_note TEXT NOT NULL,PRIMARY KEY(version_id,position),UNIQUE(version_id,task_id),FOREIGN KEY(task_id,task_revision) REFERENCES task_events(task_id,revision));
CREATE TABLE staff_cover_events(id TEXT PRIMARY KEY,root_id TEXT NOT NULL REFERENCES staff_cover_roots(id),version_id TEXT NOT NULL REFERENCES staff_cover_versions(id),store_id TEXT NOT NULL REFERENCES stores(id),revision INTEGER NOT NULL CHECK(revision>0),sequence INTEGER NOT NULL CHECK(sequence>0),action TEXT NOT NULL CHECK(action IN('plan','withdraw')),status TEXT NOT NULL CHECK(status IN('planned','withdrawn')),reason TEXT NOT NULL,next_step TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(root_id,revision),UNIQUE(store_id,sequence),UNIQUE(id,version_id));
CREATE VIEW staff_cover_current AS SELECT * FROM staff_cover_events e WHERE revision=(SELECT max(revision) FROM staff_cover_events WHERE root_id=e.root_id);
CREATE TRIGGER staff_cover_root_source BEFORE INSERT ON staff_cover_roots BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM staff_record_roots r WHERE r.id=NEW.absence_id AND r.kind='absence' AND r.staff_id=NEW.staff_id AND r.store_id=NEW.store_id) OR NEW.serial<>coalesce((SELECT max(serial)+1 FROM staff_cover_roots WHERE store_id=NEW.store_id),1) OR NEW.cover_number IS NOT 'SC-'||replace(substr(NEW.created_at,1,10),'-','')||'-'||printf('%05d',NEW.serial) THEN RAISE(ABORT,'staff cover fixed absence/staff/number') END;END;
CREATE TRIGGER staff_cover_version_source BEFORE INSERT ON staff_cover_versions BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM staff_cover_roots r JOIN staff_record_current e ON e.root_id=r.absence_id JOIN staff_record_versions v ON v.id=e.version_id WHERE r.id=NEW.root_id AND r.store_id=NEW.store_id AND e.status='recorded' AND e.id=NEW.absence_event_id AND v.id=NEW.absence_version_id AND v.root_id=r.absence_id AND e.created_at<=NEW.created_at) OR NEW.version<>coalesce((SELECT max(version)+1 FROM staff_cover_versions WHERE root_id=NEW.root_id),1) OR NEW.base_sequence<>coalesce((SELECT max(sequence) FROM staff_cover_events WHERE store_id=NEW.store_id),0) OR NEW.task_completion_prefix<>coalesce((SELECT max(c.rowid) FROM task_completions c JOIN work_tasks t ON t.id=c.task_id WHERE t.store_id=NEW.store_id),0) OR NEW.task_event_prefix<>coalesce((SELECT max(e.rowid) FROM task_events e JOIN work_tasks t ON t.id=e.task_id WHERE t.store_id=NEW.store_id),0) OR NEW.staff_record_sequence<>coalesce((SELECT max(sequence) FROM staff_record_events WHERE store_id=NEW.store_id),0) OR NEW.version=1 AND NOT EXISTS(SELECT 1 FROM staff_cover_roots r WHERE r.id=NEW.root_id AND r.first_version_id=NEW.id AND r.created_at=NEW.created_at AND r.created_by=NEW.created_by) THEN RAISE(ABORT,'staff cover current absence/version pairing') END;END;
CREATE TRIGGER staff_cover_item_source BEFORE INSERT ON staff_cover_items BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM staff_cover_versions v JOIN staff_cover_roots r ON r.id=v.root_id JOIN work_tasks t ON t.id=NEW.task_id JOIN task_events e ON e.task_id=t.id AND e.revision=NEW.task_revision JOIN users u ON u.id=NEW.recipient_id LEFT JOIN user_security sec ON sec.user_id=u.id WHERE v.id=NEW.version_id AND NEW.position<=v.item_count AND t.store_id=r.store_id AND t.assignee_id=r.staff_id AND t.revision=NEW.task_revision AND t.lifecycle_status<>'cancelled' AND e.assignee_id=r.staff_id AND e.created_at<=v.created_at AND e.rowid<=v.task_event_prefix AND NOT EXISTS(SELECT 1 FROM task_completions WHERE task_id=t.id) AND u.id<>r.staff_id AND u.store_id=r.store_id AND u.role<>'guardian' AND u.active=1 AND coalesce(sec.must_change_password,0)=0) OR NEW.position<>coalesce((SELECT max(position)+1 FROM staff_cover_items WHERE version_id=NEW.version_id),1) OR EXISTS(SELECT 1 FROM staff_cover_events WHERE version_id=NEW.version_id) THEN RAISE(ABORT,'staff cover current original task/recipient') END;END;
CREATE TRIGGER staff_cover_event_source BEFORE INSERT ON staff_cover_events BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM staff_cover_versions v WHERE v.id=NEW.version_id AND v.root_id=NEW.root_id AND v.store_id=NEW.store_id) OR NEW.sequence<>coalesce((SELECT max(sequence)+1 FROM staff_cover_events WHERE store_id=NEW.store_id),1) OR NEW.revision<>coalesce((SELECT max(revision)+1 FROM staff_cover_events WHERE root_id=NEW.root_id),1) OR NEW.action='plan' AND (NEW.status<>'planned' OR NOT EXISTS(SELECT 1 FROM staff_cover_versions v WHERE v.id=NEW.version_id AND v.event_id=NEW.id AND v.base_sequence+1=NEW.sequence AND v.created_at=NEW.created_at AND v.created_by=NEW.created_by AND v.reason=NEW.reason AND v.item_count=(SELECT count(*) FROM staff_cover_items WHERE version_id=v.id) AND v.version=coalesce((SELECT max(p.version)+1 FROM staff_cover_events e JOIN staff_cover_versions p ON p.id=e.version_id WHERE e.root_id=NEW.root_id),1))) THEN RAISE(ABORT,'staff cover complete paired event') END; SELECT CASE WHEN NEW.action='withdraw' AND (NEW.status<>'withdrawn' OR NOT EXISTS(SELECT 1 FROM staff_cover_current e WHERE e.root_id=NEW.root_id AND e.status='planned' AND e.version_id=NEW.version_id)) THEN RAISE(ABORT,'staff cover current explicit withdrawal') END;END;
CREATE TRIGGER staff_cover_staff_snapshot BEFORE INSERT ON staff_cover_versions WHEN NEW.staff_snapshot_json IS NOT (SELECT json_object('id',u.id,'display_name',u.display_name,'role',u.role,'store_id',u.store_id,'active',u.active,'revision',coalesce(s.revision,1),'must_change_password',coalesce(s.must_change_password,0)) FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=(SELECT staff_id FROM staff_cover_roots WHERE id=NEW.root_id) AND u.store_id=NEW.store_id AND u.role<>'guardian') BEGIN SELECT RAISE(ABORT,'staff cover original current staff snapshot');END;
CREATE TRIGGER staff_cover_recipient_snapshot BEFORE INSERT ON staff_cover_items WHEN NEW.recipient_snapshot_json IS NOT (SELECT json_object('id',u.id,'display_name',u.display_name,'role',u.role,'store_id',u.store_id,'active',u.active,'revision',coalesce(s.revision,1),'must_change_password',coalesce(s.must_change_password,0)) FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.recipient_id AND u.store_id=(SELECT store_id FROM staff_cover_versions WHERE id=NEW.version_id) AND u.role<>'guardian') BEGIN SELECT RAISE(ABORT,'staff cover original current recipient snapshot');END;
CREATE TRIGGER staff_cover_roots_actor BEFORE INSERT ON staff_cover_roots WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.role='manager' AND u.active=1 AND coalesce(s.must_change_password,0)=0) OR length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR EXISTS(SELECT 1 FROM staff_cover_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'staff cover current actor/time');END;
CREATE TRIGGER staff_cover_versions_actor BEFORE INSERT ON staff_cover_versions WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.role='manager' AND u.active=1 AND coalesce(s.must_change_password,0)=0) OR length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR EXISTS(SELECT 1 FROM staff_cover_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'staff cover current actor/time');END;
CREATE TRIGGER staff_cover_events_actor BEFORE INSERT ON staff_cover_events WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.role='manager' AND u.active=1 AND coalesce(s.must_change_password,0)=0) OR length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR EXISTS(SELECT 1 FROM staff_cover_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'staff cover current actor/time');END;
CREATE TRIGGER staff_cover_roots_no_update BEFORE UPDATE ON staff_cover_roots BEGIN SELECT RAISE(ABORT,'staff cover immutable');END;
CREATE TRIGGER staff_cover_roots_no_delete BEFORE DELETE ON staff_cover_roots BEGIN SELECT RAISE(ABORT,'staff cover immutable');END;
CREATE TRIGGER staff_cover_versions_no_update BEFORE UPDATE ON staff_cover_versions BEGIN SELECT RAISE(ABORT,'staff cover immutable');END;
CREATE TRIGGER staff_cover_versions_no_delete BEFORE DELETE ON staff_cover_versions BEGIN SELECT RAISE(ABORT,'staff cover immutable');END;
CREATE TRIGGER staff_cover_items_no_update BEFORE UPDATE ON staff_cover_items BEGIN SELECT RAISE(ABORT,'staff cover immutable');END;
CREATE TRIGGER staff_cover_items_no_delete BEFORE DELETE ON staff_cover_items BEGIN SELECT RAISE(ABORT,'staff cover immutable');END;
CREATE TRIGGER staff_cover_events_no_update BEFORE UPDATE ON staff_cover_events BEGIN SELECT RAISE(ABORT,'staff cover immutable');END;
CREATE TRIGGER staff_cover_events_no_delete BEFORE DELETE ON staff_cover_events BEGIN SELECT RAISE(ABORT,'staff cover immutable');END;
CREATE TRIGGER staff_cover_versions_text BEFORE INSERT ON staff_cover_versions WHEN length(trim(NEW.title)) NOT BETWEEN 1 AND 160 OR length(NEW.title)>160 OR instr(NEW.title,char(0))>0 OR length(trim(NEW.source_reference)) NOT BETWEEN 1 AND 1000 OR length(NEW.source_reference)>1000 OR instr(NEW.source_reference,char(0))>0 OR length(trim(NEW.source_note)) NOT BETWEEN 1 AND 2000 OR length(NEW.source_note)>2000 OR instr(NEW.source_note,char(0))>0 OR length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 OR length(NEW.reason)>300 OR instr(NEW.reason,char(0))>0 BEGIN SELECT RAISE(ABORT,'staff cover explicit source text');END;
CREATE TRIGGER staff_cover_items_text BEFORE INSERT ON staff_cover_items WHEN length(trim(NEW.coverage_note)) NOT BETWEEN 1 AND 2000 OR length(NEW.coverage_note)>2000 OR instr(NEW.coverage_note,char(0))>0 BEGIN SELECT RAISE(ABORT,'staff cover explicit source text');END;
CREATE TRIGGER staff_cover_events_text BEFORE INSERT ON staff_cover_events WHEN length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 OR length(NEW.reason)>300 OR instr(NEW.reason,char(0))>0 OR length(trim(NEW.next_step)) NOT BETWEEN 1 AND 2000 OR length(NEW.next_step)>2000 OR instr(NEW.next_step,char(0))>0 BEGIN SELECT RAISE(ABORT,'staff cover explicit source text');END;
